/**
 * Minimal date helpers. These replace the handful of `date-fns` functions the
 * app actually used, plus the calendar arithmetic `ui/DatePicker` needs.
 *
 * Every function is pure and returns a new `Date`; the input is never mutated.
 */

const MS_PER_DAY = 86_400_000;

export function setHours(date: Date, hours: number): Date {
  const next = new Date(date.getTime());
  next.setHours(hours);

  return next;
}

export function setMinutes(date: Date, minutes: number): Date {
  const next = new Date(date.getTime());
  next.setMinutes(minutes);

  return next;
}

export function startOfDay(date: Date): Date {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate());
}

export function startOfMonth(date: Date): Date {
  return new Date(date.getFullYear(), date.getMonth(), 1);
}

export function endOfMonth(date: Date): Date {
  return new Date(date.getFullYear(), date.getMonth() + 1, 0);
}

/**
 * Adds `amount` months, clamping the day so that e.g. Jan 31 + 1 month lands on
 * the last day of February rather than spilling into March.
 */
export function addMonths(date: Date, amount: number): Date {
  const targetMonthStart = new Date(
    date.getFullYear(),
    date.getMonth() + amount,
    1,
  );
  const daysInTargetMonth = endOfMonth(targetMonthStart).getDate();

  return new Date(
    targetMonthStart.getFullYear(),
    targetMonthStart.getMonth(),
    Math.min(date.getDate(), daysInTargetMonth),
    date.getHours(),
    date.getMinutes(),
    date.getSeconds(),
    date.getMilliseconds(),
  );
}

export function addDays(date: Date, amount: number): Date {
  const next = new Date(date.getTime());
  next.setDate(next.getDate() + amount);

  return next;
}

/**
 * `weekStartsOn` follows the JS convention: 0 = Sunday … 6 = Saturday.
 */
export function startOfWeek(date: Date, weekStartsOn = 0): Date {
  const dayOfMonth = startOfDay(date);
  const diff = (dayOfMonth.getDay() - weekStartsOn + 7) % 7;

  return addDays(dayOfMonth, -diff);
}

export function isSameDay(left: Date, right: Date): boolean {
  return (
    left.getFullYear() === right.getFullYear() &&
    left.getMonth() === right.getMonth() &&
    left.getDate() === right.getDate()
  );
}

export function isSameMonth(left: Date, right: Date): boolean {
  return (
    left.getFullYear() === right.getFullYear() &&
    left.getMonth() === right.getMonth()
  );
}

/**
 * Compares two dates by calendar month only, returning the usual -1 / 0 / 1.
 */
export function compareMonths(left: Date, right: Date): number {
  const leftIndex = left.getFullYear() * 12 + left.getMonth();
  const rightIndex = right.getFullYear() * 12 + right.getMonth();

  if (leftIndex === rightIndex) {
    return 0;
  }

  return leftIndex < rightIndex ? -1 : 1;
}

/**
 * Restricts `date` to the `[start, end]` month range, preserving the day when
 * no clamping is needed.
 */
export function clampMonth(date: Date, start: Date, end: Date): Date {
  if (compareMonths(date, start) < 0) {
    return startOfMonth(start);
  }

  if (compareMonths(date, end) > 0) {
    return startOfMonth(end);
  }

  return startOfMonth(date);
}

/**
 * Whole days between two dates, ignoring the time of day. Positive when `right`
 * is later than `left`.
 */
export function differenceInCalendarDays(left: Date, right: Date): number {
  return Math.round(
    (startOfDay(right).getTime() - startOfDay(left).getTime()) / MS_PER_DAY,
  );
}
