import type { JSX, KeyboardEvent } from 'react';

import './index.scss';

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';

import {
  addDays,
  addMonths,
  clampMonth,
  compareMonths,
  endOfMonth,
  isSameDay,
  isSameMonth,
  startOfDay,
  startOfMonth,
  startOfWeek,
} from '../../utils/dateMath';

const DAYS_PER_WEEK = 7;
const FIXED_WEEK_COUNT = 6;

/**
 * Pinned rather than following the system locale so month and weekday names
 * render exactly as they did before. Switching to the user's locale is a
 * one-line change here.
 */
const LOCALE = 'en-US';

const monthNameFormatter = new Intl.DateTimeFormat(LOCALE, { month: 'long' });
const weekdayShortFormatter = new Intl.DateTimeFormat(LOCALE, {
  weekday: 'short',
});
const weekdayLongFormatter = new Intl.DateTimeFormat(LOCALE, {
  weekday: 'long',
});
const dayLabelFormatter = new Intl.DateTimeFormat(LOCALE, {
  day: 'numeric',
  month: 'long',
  year: 'numeric',
});

export type DatePickerProps = Readonly<{
  captionLayout?: 'dropdown' | 'label';
  endMonth: Date;
  fixedWeeks?: boolean;
  mode?: 'single';
  navLayout?: 'after';
  onSelect: (date: Date | undefined) => void;
  /** When true, clicking the selected day re-selects it instead of clearing. */
  required?: boolean;
  selected: Date | undefined;
  showOutsideDays?: boolean;
  startMonth: Date;
}>;

type ChevronOrientation = 'down' | 'left' | 'right';

const CHEVRON_POINTS: Readonly<Record<ChevronOrientation, string>> = {
  down: '6.77 8 12.5 13.57 18.24 8 20 9.72 12.5 17 5 9.72',
  left: '16 18.112 9.81111111 12 16 5.87733333 14.0888889 4 6 12 14.0888889 20',
  right:
    '8 18.112 14.18888889 12 8 5.87733333 9.91111111 4 18 12 9.91111111 20',
};

function Chevron({
  orientation,
  size = 24,
}: Readonly<{
  orientation: ChevronOrientation;
  size?: number;
}>): JSX.Element {
  return (
    <svg
      aria-hidden="true"
      className="rdp-chevron"
      height={size}
      viewBox="0 0 24 24"
      width={size}
    >
      <polygon points={CHEVRON_POINTS[orientation]} />
    </svg>
  );
}

/**
 * Builds the week rows for `month`. Each cell carries the date it renders plus
 * whether it spills out of the displayed month.
 */
function buildWeeks(
  month: Date,
  fixedWeeks: boolean,
): Array<Array<{ date: Date; isOutside: boolean }>> {
  const gridStart = startOfWeek(startOfMonth(month));
  const lastDayOfMonth = endOfMonth(month);
  const daysToRender =
    Math.round(
      (startOfDay(lastDayOfMonth).getTime() - gridStart.getTime()) / 86_400_000,
    ) + 1;
  const weekCount = fixedWeeks
    ? FIXED_WEEK_COUNT
    : Math.ceil(daysToRender / DAYS_PER_WEEK);

  return Array.from({ length: weekCount }, (_unusedWeek, weekIndex) =>
    Array.from({ length: DAYS_PER_WEEK }, (_unusedDay, dayIndex) => {
      const date = addDays(gridStart, weekIndex * DAYS_PER_WEEK + dayIndex);

      return { date, isOutside: !isSameMonth(date, month) };
    }),
  );
}

/**
 * A single-date calendar. The DOM and class names mirror the structure this
 * component replaced so the surrounding theme stylesheet keeps applying.
 */
export default function DatePicker({
  captionLayout = 'label',
  endMonth,
  fixedWeeks = false,
  navLayout,
  onSelect,
  required = false,
  selected,
  showOutsideDays = false,
  startMonth,
}: DatePickerProps): JSX.Element {
  const firstAllowedMonth = useMemo(
    () => startOfMonth(startMonth),
    [startMonth],
  );
  const lastAllowedMonth = useMemo(() => startOfMonth(endMonth), [endMonth]);

  const [displayMonth, setDisplayMonth] = useState(() =>
    clampMonth(selected ?? new Date(), firstAllowedMonth, lastAllowedMonth),
  );

  // Which day owns the roving tab stop. Null until the user navigates by
  // keyboard, so opening the calendar does not steal focus.
  const [focusedDate, setFocusedDate] = useState<Date | null>(null);
  const gridRef = useRef<HTMLTableElement>(null);
  const shouldRestoreFocus = useRef(false);

  const today = useMemo(() => startOfDay(new Date()), []);
  const weeks = useMemo(
    () => buildWeeks(displayMonth, fixedWeeks),
    [displayMonth, fixedWeeks],
  );

  const canGoToPreviousMonth =
    compareMonths(displayMonth, firstAllowedMonth) > 0;
  const canGoToNextMonth = compareMonths(displayMonth, lastAllowedMonth) < 0;

  const isDayDisabled = useCallback(
    (date: Date): boolean =>
      compareMonths(date, firstAllowedMonth) < 0 ||
      compareMonths(date, lastAllowedMonth) > 0,
    [firstAllowedMonth, lastAllowedMonth],
  );

  // The tab stop follows keyboard focus, then the selection, then day one.
  const tabStopDate = useMemo(() => {
    if (focusedDate !== null && isSameMonth(focusedDate, displayMonth)) {
      return focusedDate;
    }

    if (selected !== undefined && isSameMonth(selected, displayMonth)) {
      return startOfDay(selected);
    }

    if (isSameMonth(today, displayMonth)) {
      return today;
    }

    return startOfMonth(displayMonth);
  }, [displayMonth, focusedDate, selected, today]);

  useEffect(() => {
    if (!shouldRestoreFocus.current || gridRef.current === null) {
      return;
    }

    shouldRestoreFocus.current = false;
    const activeDayButton = gridRef.current.querySelector<HTMLButtonElement>(
      '.rdp-day_button[tabindex="0"]',
    );
    activeDayButton?.focus();
  }, [tabStopDate]);

  const goToMonth = useCallback(
    (month: Date) => {
      setDisplayMonth(clampMonth(month, firstAllowedMonth, lastAllowedMonth));
    },
    [firstAllowedMonth, lastAllowedMonth],
  );

  const moveFocus = useCallback(
    (date: Date) => {
      if (isDayDisabled(date)) {
        return;
      }

      shouldRestoreFocus.current = true;
      setFocusedDate(date);

      if (!isSameMonth(date, displayMonth)) {
        goToMonth(date);
      }
    },
    [displayMonth, goToMonth, isDayDisabled],
  );

  const handleDayKeyDown = useCallback(
    (event: KeyboardEvent<HTMLButtonElement>, date: Date) => {
      const moves: Readonly<Record<string, () => Date>> = {
        ArrowDown: () => addDays(date, DAYS_PER_WEEK),
        ArrowLeft: () => addDays(date, -1),
        ArrowRight: () => addDays(date, 1),
        ArrowUp: () => addDays(date, -DAYS_PER_WEEK),
        End: () => addDays(startOfWeek(date), DAYS_PER_WEEK - 1),
        Home: () => startOfWeek(date),
        PageDown: () => addMonths(date, 1),
        PageUp: () => addMonths(date, -1),
      };

      const move = moves[event.key];

      if (move === undefined) {
        return;
      }

      event.preventDefault();
      moveFocus(move());
    },
    [moveFocus],
  );

  const handleDayClick = useCallback(
    (date: Date) => {
      setFocusedDate(date);

      // Without `required`, clicking the current selection clears it.
      if (!required && selected !== undefined && isSameDay(selected, date)) {
        onSelect(undefined);
        return;
      }

      onSelect(date);
    },
    [onSelect, required, selected],
  );

  const monthOptions = useMemo(() => {
    const year = displayMonth.getFullYear();
    const firstMonth =
      year === firstAllowedMonth.getFullYear()
        ? firstAllowedMonth.getMonth()
        : 0;
    const lastMonth =
      year === lastAllowedMonth.getFullYear()
        ? lastAllowedMonth.getMonth()
        : 11;

    return Array.from(
      { length: lastMonth - firstMonth + 1 },
      (_unused, index) => firstMonth + index,
    );
  }, [displayMonth, firstAllowedMonth, lastAllowedMonth]);

  const yearOptions = useMemo(() => {
    const firstYear = firstAllowedMonth.getFullYear();
    const lastYear = lastAllowedMonth.getFullYear();

    return Array.from(
      { length: lastYear - firstYear + 1 },
      (_unused, index) => firstYear + index,
    );
  }, [firstAllowedMonth, lastAllowedMonth]);

  const weekdays = useMemo(() => {
    const weekStart = startOfWeek(new Date());

    return Array.from({ length: DAYS_PER_WEEK }, (_unused, index) =>
      addDays(weekStart, index),
    );
  }, []);

  const monthLabel = `${monthNameFormatter.format(
    displayMonth,
  )} ${displayMonth.getFullYear()}`;

  return (
    <div className="rdp-root" data-nav-layout={navLayout} role="application">
      <div className="rdp-months">
        <div className="rdp-month">
          <div className="rdp-month_caption">
            {captionLayout === 'dropdown' ? (
              <div className="rdp-dropdowns">
                <span className="rdp-dropdown_root">
                  <select
                    aria-label="Month"
                    className="rdp-dropdown"
                    onChange={(event) => {
                      goToMonth(
                        new Date(
                          displayMonth.getFullYear(),
                          Number(event.target.value),
                          1,
                        ),
                      );
                    }}
                    value={displayMonth.getMonth()}
                  >
                    {monthOptions.map((monthIndex) => (
                      <option key={monthIndex} value={monthIndex}>
                        {monthNameFormatter.format(
                          new Date(displayMonth.getFullYear(), monthIndex, 1),
                        )}
                      </option>
                    ))}
                  </select>
                  <span aria-hidden="true" className="rdp-caption_label">
                    {monthNameFormatter.format(displayMonth)}
                    <Chevron orientation="down" size={18} />
                  </span>
                </span>
                <span className="rdp-dropdown_root">
                  <select
                    aria-label="Year"
                    className="rdp-dropdown"
                    onChange={(event) => {
                      goToMonth(
                        new Date(
                          Number(event.target.value),
                          displayMonth.getMonth(),
                          1,
                        ),
                      );
                    }}
                    value={displayMonth.getFullYear()}
                  >
                    {yearOptions.map((year) => (
                      <option key={year} value={year}>
                        {year}
                      </option>
                    ))}
                  </select>
                  <span aria-hidden="true" className="rdp-caption_label">
                    {displayMonth.getFullYear()}
                    <Chevron orientation="down" size={18} />
                  </span>
                </span>
              </div>
            ) : (
              <span className="rdp-caption_label">{monthLabel}</span>
            )}
          </div>
          <nav className="rdp-nav">
            <button
              aria-label="Go to the previous month"
              className="rdp-button_previous"
              disabled={!canGoToPreviousMonth}
              onClick={() => {
                goToMonth(addMonths(displayMonth, -1));
              }}
              type="button"
            >
              <Chevron orientation="left" size={18} />
            </button>
            <button
              aria-label="Go to the next month"
              className="rdp-button_next"
              disabled={!canGoToNextMonth}
              onClick={() => {
                goToMonth(addMonths(displayMonth, 1));
              }}
              type="button"
            >
              <Chevron orientation="right" size={18} />
            </button>
          </nav>
          <table
            aria-label={monthLabel}
            className="rdp-month_grid"
            ref={gridRef}
            role="grid"
          >
            <thead>
              <tr className="rdp-weekdays">
                {weekdays.map((weekday) => (
                  <th
                    abbr={weekdayLongFormatter.format(weekday)}
                    className="rdp-weekday"
                    key={weekday.getDay()}
                    scope="col"
                  >
                    {weekdayShortFormatter.format(weekday)}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody className="rdp-weeks">
              {weeks.map((week) => (
                <tr className="rdp-week" key={week[0].date.getTime()}>
                  {week.map(({ date, isOutside }) => {
                    if (isOutside && !showOutsideDays) {
                      return (
                        <td
                          className="rdp-day"
                          key={date.getTime()}
                          role="gridcell"
                        />
                      );
                    }

                    const isSelected =
                      selected !== undefined && isSameDay(selected, date);
                    const isToday = isSameDay(today, date);
                    const isDisabled = isDayDisabled(date);
                    const classNames = [
                      'rdp-day',
                      isSelected ? 'rdp-selected' : '',
                      isToday ? 'rdp-today' : '',
                      isOutside ? 'rdp-outside' : '',
                      isDisabled ? 'rdp-disabled' : '',
                    ]
                      .filter(Boolean)
                      .join(' ');

                    return (
                      <td
                        aria-selected={isSelected}
                        className={classNames}
                        key={date.getTime()}
                        role="gridcell"
                      >
                        <button
                          aria-label={dayLabelFormatter.format(date)}
                          className="rdp-day_button"
                          disabled={isDisabled}
                          onClick={() => {
                            handleDayClick(date);
                          }}
                          onKeyDown={(event) => {
                            handleDayKeyDown(event, date);
                          }}
                          tabIndex={isSameDay(tabStopDate, date) ? 0 : -1}
                          type="button"
                        >
                          {date.getDate()}
                        </button>
                      </td>
                    );
                  })}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}
